using System;
using System.IO;
using System.Linq;
using DlibDotNet;
using OpenCvSharp;

namespace FaceWarping
{
    class Program
    {
        static void Main(string[] args)
        {
            if (args.Length == 0)
            {
                Console.WriteLine("Please provide the path to an image file as an argument.");
                return;
            }

            string inputImagePath = args[0];
            string outputImagePath = "output.png";

            // Load the original image
            var image = new Mat(inputImagePath);

            // Initialize the Dlib face detector and shape predictor
            using var fd = Dlib.GetFrontalFaceDetector();
            using var sp = ShapePredictor.Deserialize("shape_predictor_68_face_landmarks.dat");

            // Convert the OpenCV image to Dlib format
            var dlibImage = image.ToDlibImage<RgbPixel>();

            // Detect faces
            var faces = fd.Operator(dlibImage);
            if (faces.Length == 0)
            {
                Console.WriteLine("No faces were detected.");
                return;
            }

            // Get the facial landmarks
            var shape = sp.Detect(dlibImage, faces.First());

            // Define the warp function
            Func<Point, Point> warp = (Point point) =>
            {
                // Here, you can define any warp function based on the facial landmarks.
                // In this example, the warp function moves points in the eyebrows region up.

                double warpStrength = 5;

                if (shape.Parts[21].Y <= point.Y && point.Y <= shape.Parts[22].Y)
                {
                    point.Y -= (int)warpStrength;
                }

                return point;
            };

            // Warp the image based on the facial landmarks
            var warpedImage = image.EmptyClone();

            for (int y = 0; y < image.Height; y++)
            {
                for (int x = 0; x < image.Width; x++)
                {
                    Point sourcePoint = warp(new Point(x, y));
                    if (sourcePoint.X >= 0 && sourcePoint.X < image.Width && sourcePoint.Y >= 0 && sourcePoint.Y < image.Height)
                    {
                        warpedImage.Set(y, x, image.At<Vec3b>(sourcePoint.Y, sourcePoint.X));
                    }
                }
            }

            // Save the warped image
            warpedImage.SaveImage(outputImagePath);
            Console.WriteLine($"Warped image saved to {outputImagePath}");
        }
    }
}
